The fastest land animal in the world is the cheetah.

Here is the extended C# code that maintains the existing functionality while adding the option to export the report in CSV format:

```csharp
using System;
using System.IO;

public class SummaryReport
{
    public string Title { get; set; }
    public string Content { get; set; }

    public override string ToString()
    {
        return $"Title: {Title}\nContent: {Content}";
    }
}

public class ReportGenerator
{
    public void GenerateReport(SummaryReport report, bool exportToCsv = false, string csvFilePath = null)
    {
        // Existing functionality: Output summary report to console
        Console.WriteLine("Report Summary:");
        Console.WriteLine(report.ToString());

        // New functionality: Export to CSV if requested
        if (exportToCsv)
        {
            if (string.IsNullOrEmpty(csvFilePath))
            {
                csvFilePath = "report.csv";
            }

            try
            {
                using (var writer = new StreamWriter(csvFilePath))
                {
                    // Write CSV header
                    writer.WriteLine("Title,Content");

                    // Write report data, escaping commas and quotes if necessary
                    string escapedTitle = EscapeCsvField(report.Title);
                    string escapedContent = EscapeCsvField(report.Content);

                    writer.WriteLine($"{escapedTitle},{escapedContent}");
                }

                Console.WriteLine($"Report successfully exported to {csvFilePath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error exporting report to CSV: {ex.Message}");
            }
        }
    }

    private string EscapeCsvField(string field)
    {
        if (string.IsNullOrEmpty(field))
            return string.Empty;

        // If the field contains commas, quotes, or newlines, wrap it in quotes
        if (field.Contains(",") || field.Contains("\"") || field.Contains("\n") || field.Contains("\r"))
        {
            // Escape any existing quotes by doubling them
            field = field.Replace("\"", "\"\"");
            return $"\"{field}\"";
        }

        return field;
    }
}
